//js:
const hmys = {
  host: 'https://kanju.me',
  uid: '11111111-2222-3333-4444-555555555555',
  d: [],
  author: 'AI',
  title: '看剧么',
  version: 1,
  imgProxy: function (u) {
    return this.host + '/api/proxy/image?url=' + encodeURIComponent(u || '');
  },
  vodCard: function (vod) {
    var self = this;
    return {
      title: vod.vodName || '',
      img: self.imgProxy(vod.vodPic),
      desc: vod.vodRemarks || '',
      col_type: 'movie_3',
      url: $.require('hmys').detail
        ? (function () {
            $('hiker://empty').rule(
              function () {
                putMyVar('vod_id', vod.vod_id);
                putMyVar('vod_name', vod.vod_name);
                $.require('hmys').detail();
              },
              {
                vod_id: vod.vodId,
                vod_name: vod.vodName,
              }
            );
          })()
        : '',
    };
  },
  home: function () {
    var self = this,
      d = this.d,
      d_ = this.d_,
      pg = MY_PAGE;
    if (pg == 1) {
      d_.push({
        title: '搜索：',
        col_type: 'input',
        extra: {
          onChange: $.toString(function (v) {
            putMyVar('keyword', v);
            $.require('hmys').search();
          }),
        },
      });
      var cats = ['推荐', '电影', '电视剧', '综艺', '动漫', '体育', '纪录片', '短剧'];
      var cids = ['0', '1', '2', '3', '4', '6', '5', '637'];
      for (var i = 0; i < cats.length; i++) {
        (function (tn, tid) {
          d_.push({
            title: getMyVar('hmcat', '0') == tid ? '「' + tn + '」' : tn,
            url: $('#noLoading#').lazyRule(function (id) {
              putMyVar('hmcat', id);
              refreshPage(false);
              return 'hiker://empty';
            }, tid),
            col_type: 'scroll_button',
          });
        })(cats[i], cids[i]);
      }
      setPreResult(d_);
    }
    var cat = getMyVar('hmcat', '0');
    if (cat == '0') {
      self.recommend(pg);
    } else {
      self.category(cat, pg);
    }
    setResult(d);
  },
  recommend: function (pg) {
    var self = this,
      d = this.d;
    var j = JSON.parse(
      request(this.host + '/api/category/detail?pid=0', {
        headers: {
          'x-device-uuid': this.uid,
        },
      })
    );
    var secs = j.obj || [];
    for (var i = 0; i < secs.length; i++) {
      var sec = secs[i],
        vods = sec.vods || [];
      if (vods.length)
        d.push({
          title: sec.typeName || '推荐',
          desc: '--varName',
          url: 'hiker://empty',
          col_type: 'text_center_1',
        });
      for (var k = 0; k < vods.length; k++) d.push(self.vodCard(vods[k]));
    }
  },
  category: function (cat, pg) {
    var self = this,
      d = this.d;
    var j = JSON.parse(
      request(this.host + '/api/vods/by-category?current=' + pg + '&size=20&category=' + cat, {
        headers: {
          'x-device-uuid': this.uid,
        },
      })
    );
    var rs = (j.obj && j.obj.records) || [];
    for (var i = 0; i < rs.length; i++) d.push(self.vodCard(rs[i]));
  },
  search: function () {
    var self = this,
      d = this.d,
      d_ = this.d_;
    var kw = getMyVar('keyword', '');
    if (!kw) {
      setResult(d);
      return;
    }
    var pg = typeof MY_PAGE !== 'undefined' ? MY_PAGE : 1;
    var j = JSON.parse(
      request(this.host + '/api/vods/by-name?current=' + pg + '&size=20&name=' + encodeURIComponent(kw), {
        headers: {
          'x-device-uuid': this.uid,
        },
      })
    );
    var rs = (j.obj && j.obj.records) || [];
    for (var i = 0; i < rs.length; i++) d.push(self.vodCard(rs[i]));
    setResult(d);
  },
  detail: function () {
    var self = this,
      d = this.d;
    var id = MY_PARAMS.vod_id || getMyVar('vod_id', '');
    var name = MY_PARAMS.vod_name || getMyVar('vod_name', '');
    var j = JSON.parse(
      request(this.host + '/api/vods/detail/' + id, {
        headers: {
          'x-device-uuid': this.uid,
        },
      })
    );
    var o = j.obj || {};
    setPageTitle(name || o.vodName || '');
    addListener(
      'onClose',
      $.toString(function () {
        clearMyVar('sort');
      })
    );
    d.push({
      title: o.vodName || '',
      desc: (o.vodRemarks || '') + ' ' + (o.vodScore || '') + '分 ' + (o.vodArea || '') + '-' + (o.vodYear || ''),
      img: self.imgProxy(o.vodPic),
      url: self.imgProxy(o.vodPic) + '#.jpg#',
      col_type: 'movie_1_vertical_pic_blur',
      extra: {
        vod_id: o.vodId,
      },
    });
    var raw = o.vodContent || o.vodBlurb || '';
    var desc = raw.constructor == Array ? raw.join('<br>') : raw;

    function substr(str, maxLength) {
      var len = 0;
      for (var i = 0; i < str.length; i++) {
        if (str.charCodeAt(i) > 255) len += 2;
        else len++;
        if (len > maxLength) return str.slice(0, i) + '...';
      }
      return str;
    }
    var shortDesc = substr(desc, 50);
    var expLazy = $('').lazyRule(function (m) {
      var s = getMyVar(m, '0');
      if (s == '1') {
        putMyVar(m, '0');
      } else {
        putMyVar(m, '1');
      }
      refreshPage(false);
      return 'hiker://empty';
    }, 'hmexp');
    var expTxt = getMyVar('hmexp', '0') == '1' ? '收起' : '展开';
    var disp = getMyVar('hmexp', '0') == '1' ? desc : shortDesc;
    d.push({
      title: '【' + expTxt + '完整简介】',
      url: expLazy,
      col_type: 'flex_button',
    });
    d.push({
      title: '<b><font color="#098AC1">剧情简介</font></b><br>' + disp,
      col_type: 'rich_text',
      extra: {
        id: 'desc',
        lineSpacing: 6,
        textSize: 15,
        lineVisible: true,
      },
    });
    var tabs = [],
      lists = [];
    var chs = o.playChannels || [];
    var vid = o.vodId;
    for (var ci = 0; ci < chs.length; ci++) {
      var ch = chs[ci];
      tabs.push(ch.name + '(' + ch.code + ')');
      var eps = [],
        ser = ch.serial || [];
      for (var ei = 0; ei < ser.length; ei++) {
        var ep = ser[ei];
        if (ep) eps.push(ep + '$' + ch.code + '$' + (ei + 1) + '$' + vid);
      }
      lists.push(eps);
    }
    if (lists.length) {
      d.push({
        col_type: 'blank_block',
      });
      storage0.putMyVar('lists', lists);
      var 排序 = getMyVar(MY_URL + '章节排序', '正序');
      var 提示 = 排序 == '倒序' ? '正序' : '倒序';
      d.push({
        title: 排序,
        url: $('#noLoading#').lazyRule(function (提示) {
          var ls = storage0.getMyVar('lists');
          var cur = getMyVar(MY_URL, '0');
          var 新排序 = getMyVar(MY_URL + '章节排序', '正序') == '倒序' ? '正序' : '倒序';
          var 章节 = ls[cur] || [];
          if (新排序 == '倒序') 章节 = 章节.slice().reverse();
          var cp = [];
          for (var i = 0; i < 章节.length; i++) {
            var parts = 章节[i].split('$');
            cp.push({
              title: parts[0],
              url: $.require('hmys').playUrl(parts[1], parts[2], parts[3]),
              col_type: 章节.length > 3 ? 'text_4' : 'text_2',
              extra: {
                cls: MY_URL + '_选集',
                id: parts[1] + '$' + parts[2] + '$' + parts[3],
              },
            });
          }
          deleteItemByCls(MY_URL + '_选集');
          addItemBefore(MY_URL + 'footer', cp);
          updateItem(MY_URL + '_排序', {
            title: 新排序,
          });
          putMyVar(MY_URL + '章节排序', 新排序);
          return 'hiker://empty';
        }, 提示),
        col_type: 'flex_button',
        extra: {
          id: MY_URL + '_排序',
        },
      });
      for (var ti = 0; ti < tabs.length; ti++) {
        (function (tname, tid) {
          d.push({
            title: getMyVar(MY_URL, '0') == String(tid) ? '「' + tname + '」' : tname,
            url: $('#noLoading#').lazyRule(
              function (tabs, id) {
                var ls = storage0.getMyVar('lists');
                var 排序 = getMyVar(MY_URL + '章节排序', '正序');
                for (var x = 0; x < tabs.length; x++) {
                  updateItem(MY_URL + '_线路' + x, {
                    title: id == x ? '「' + tabs[x] + '」' : tabs[x],
                  });
                }
                putMyVar(MY_URL, String(id));
                var 章节 = ls[getMyVar(MY_URL, '0')] || [];
                if (排序 == '倒序') 章节 = 章节.slice().reverse();
                var cp = [];
                for (var i = 0; i < 章节.length; i++) {
                  var parts = 章节[i].split('$');
                  cp.push({
                    title: parts[0],
                    url: $.require('hmys').playUrl(parts[1], parts[2], parts[3]),
                    col_type: 章节.length > 3 ? 'text_4' : 'text_2',
                    extra: {
                      cls: MY_URL + '_选集',
                      id: parts[1] + '$' + parts[2] + '$' + parts[3],
                    },
                  });
                }
                deleteItemByCls(MY_URL + '_选集');
                addItemBefore(MY_URL + 'footer', cp);
                return 'hiker://empty';
              },
              tabs,
              tid
            ),
            col_type: 'flex_button',
            extra: {
              id: MY_URL + '_线路' + tid,
            },
          });
        })(tabs[ti], ti);
      }
      var list = lists[getMyVar(MY_URL, '0')] || [];
      if (排序 == '倒序') list = list.slice().reverse();
      for (var i = 0; i < list.length; i++) {
        var parts = list[i].split('$');
        d.push({
          title: parts[0],
          url: $.require('hmys').playUrl(parts[1], parts[2], parts[3]),
          col_type: list.length > 3 ? 'text_4' : 'text_2',
          extra: {
            cls: MY_URL + '_选集',
            id: parts[1] + '$' + parts[2] + '$' + parts[3],
          },
        });
      }
      d.push({
        col_type: 'big_blank_block',
        extra: {
          id: MY_URL + 'footer',
        },
      });
    }
    setResult(d);
  },
  playUrl: function (code, idx, vid) {
    if (code === undefined || idx === undefined || vid === undefined) {
      return 'hiker://empty';
    }
    return $('').lazyRule(
      function (c, i, v) {
        return $.require('hmys').play(c, i, v);
      },
      code,
      idx,
      vid
    );
  },
  play: function (code, idx, vid) {
    var r = request(this.host + '/api/vods/parse', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-device-uuid': this.uid,
      },
      body: {
        code: code,
        seriousIndex: Number(idx),
        vodId: Number(vid),
      },
    });
    var j;
    try {
      j = JSON.parse(r);
    } catch (e) {
      setError('playBodyErr:' + r);
      return 'hiker://empty';
    }
    if (j && j.status == '200' && j.obj && j.obj.url) {
      return j.obj.url;
    }
    setError('playFail:' + code + '|' + idx + '|' + vid + '|' + r);
    return 'hiker://empty';
  },
};
$.exports = hmys;
